response:
**Gates before launch**

First, I confirm the prediction is locked. `git log` must show the `SPE r04 predict` commit, and `git diff --quiet HEAD -- spe/predictions/r04.yaml spe/plans/r04.md` must pass. Second, I run the grader selftest. `grade.py` must score the oracle (answers.json fed back as the answer set) at 50/50. It must score an empty answer set at 0 without crashing. It must score a deliberately wrong set at 0. I also run `judge.md` on 2 known-polite and 2 known-rude replies, and it must pass and fail them correctly. Third, I regrade round 3's stored labels with today's `grade.py` as a control. The category and priority accuracy must equal the round 3 numbers in `spe/prediction-log.md`. A difference means the grader changed, so I log it in `spe/failures.md` and halt. Fourth, I do a dry run with `{only: ['B:T01','C2:T01','C2:T02'], trialsPerCell: 1, topUpCap: 0, spendCapUsd: 3, transcriptDir: <round 3 value>}`. It must return schema-valid trials, grader rows for every trial, transcripts the peek scan can find, and judge scores. I use its measured spend to set `costPerTrialUsd`. If 500 trials at that cost plus synthesis would cross $40, I stop and ask you. I do this because letting the cap skip trials would change the planned n. Last, I commit the script as `SPE r04 evaluate (harness)` and launch.

**Assumptions:** I used round 3's layout. Each config's prompt and tool list are in `spe/configs/<config>/` (`prompt.md`, `tools.md`). The tickets are `spe/evals/tasks/tickets/T01.json` to `T50.json`. `grade.py` takes `--answers`, `--input`, and `--json`. If the selftest shows a different interface, I change `args.gradeCmd`.

**spe/evals/harness/r04-workflow.js**

```js
export const meta = {
  name: 'spe-round-eval',
  description: 'SPE eval: run every ticket under every config, grade labels with grade.py, scan transcripts for peeks, judge reply tone with Opus, top up split cells, then run failure analysis and a completeness critic. Spend-capped.',
  phases: [
    { title: 'Trials' },
    { title: 'Grade' },
    { title: 'Scan' },
    { title: 'Judge' },
    { title: 'Top-up' },
    { title: 'Synthesis' },
  ],
};

// ---------- Arguments ----------
const A = (typeof args !== 'undefined' && args) || {};
const ROUND = A.round ?? 4;
const pad2 = (n) => String(n).padStart(2, '0');
const R = `r${pad2(ROUND)}`;
const NEXT = `r${pad2(ROUND + 1)}`;

const CONFIGS = A.configs ?? ['B', 'C2'];
const TICKETS = A.tickets ?? Array.from({ length: A.ticketCount ?? 50 }, (_, i) => `T${pad2(i + 1)}`);
const TRIALS_PER_CELL = A.trialsPerCell ?? 5;
const TOPUP_PER_CELL = A.topUpPerCell ?? 3;
const TOPUP_CAP = A.topUpCap ?? 60;
const ONLY = A.only ?? null; // dry run, e.g. ['B:T01', 'C2:T01', 'C2:T02']
const TRANSCRIPT_DIR = A.transcriptDir ?? null;
const GRADE_CMD = A.gradeCmd ??
  'python3 spe/evals/graders/grade.py --answers spe/evals/tasks/answers.json --input {input} --json';

const TRIAL_MODEL = A.trialModel ?? 'opus';
const CLERK_MODEL = A.clerkModel ?? 'opus';
const JUDGE_MODEL = 'opus'; // fixed by the approved plan

const GRADE_CHUNK = 25;
const SCAN_CHUNK = 25;
const JUDGE_CHUNK = 10;
const MAX_FAILURES_FOR_ANALYSIS = A.maxFailuresForAnalysis ?? 150;
const UNVERIFIED_HALT_SHARE = 0.10;

// ---------- Budget (estimates; the dry run calibrates them) ----------
const CAP_USD = A.spendCapUsd ?? 40;
const COST = {
  trial: A.costPerTrialUsd ?? 0.05,
  grade: A.costPerGradeUsd ?? 0.05,
  scan: A.costPerScanUsd ?? 0.08,
  judge: A.costPerJudgeUsd ?? 0.10,
  synth: A.costPerSynthUsd ?? 0.75,
};
// Each trial reserves its share of grading, scanning, and judging up front,
// so those steps are never skipped after the trial has run.
const PER_TRIAL = 1.1 * (COST.trial + COST.grade / GRADE_CHUNK + COST.scan / SCAN_CHUNK + COST.judge / JUDGE_CHUNK);
const SYNTH_RESERVE = 2 * COST.synth;

let spent = 0;
const skipped = [];
function reserveTrial(label) {
  if (spent + PER_TRIAL > CAP_USD - SYNTH_RESERVE) {
    skipped.push(label);
    log(`SKIP ${label}: est. spend $${(spent + PER_TRIAL).toFixed(2)} would cross $${(CAP_USD - SYNTH_RESERVE).toFixed(2)} (cap $${CAP_USD} minus synthesis reserve)`);
    return false;
  }
  spent += PER_TRIAL;
  return true;
}

// ---------- Helpers ----------
let halted = null;
function halt(reason) {
  if (!halted) { halted = reason; log(`HALT: ${reason}`); }
}
let currentPhase = null;
function enter(title) {
  if (title !== currentPhase) { phase(title); currentPhase = title; }
}
function hash(s) {
  let h = 2166136261;
  for (const c of String(s)) { h ^= c.charCodeAt(0); h = Math.imul(h, 16777619); }
  return h >>> 0;
}
function chunks(arr, n) {
  const out = [];
  for (let i = 0; i < arr.length; i += n) out.push(arr.slice(i, i + n));
  return out;
}
const mean = (xs) => (xs.length ? xs.reduce((a, b) => a + b, 0) / xs.length : null);
const rate = (xs, f) => (xs.length ? xs.filter(f).length / xs.length : null);
const r3 = (x) => (x == null ? null : Math.round(x * 1000) / 1000);
const r2 = (x) => Math.round(x * 100) / 100;
const errText = (e) => String((e && e.message) || e);

// A trial may read only its own config folder and its own ticket file inside spe/.
function speRel(p) {
  const s = String(p);
  const i = s.indexOf('spe/');
  return i < 0 ? null : s.slice(i);
}
function forbiddenFor(rec) {
  return (p) => {
    const rel = speRel(p);
    if (!rel) return false;
    if (rel === `spe/configs/${rec.cfg}` || rel.startsWith(`spe/configs/${rec.cfg}/`)) return false;
    if (rel === `spe/evals/tasks/tickets/${rec.ticket}.json`) return false;
    return true;
  };
}
const isValid = (r) => r.outcome === 'completed' && !r.voided && !!r.grade;

// ---------- Schemas ----------
const TRIAL_SCHEMA = {
  type: 'object',
  required: ['ticket_id', 'label', 'reply', 'tool_calls', 'tool_errors', 'files_read', 'status'],
  properties: {
    ticket_id: { type: 'string' },
    label: {
      type: 'object',
      required: ['category', 'priority'],
      properties: { category: { type: 'string' }, priority: { type: 'string' } },
    },
    reply: { type: 'string' },
    tool_calls: { type: 'array', items: { type: 'string' } },
    tool_errors: { type: 'integer', minimum: 0 },
    files_read: { type: 'array', items: { type: 'string' } },
    status: { type: 'string', enum: ['done', 'gave_up'] },
    note: { type: 'string' },
  },
};

const GRADE_SCHEMA = {
  type: 'object',
  required: ['grader_exit_code', 'results'],
  properties: {
    grader_exit_code: { type: 'integer' },
    stderr_tail: { type: 'string' },
    results: {
      type: 'array',
      items: {
        type: 'object',
        required: ['trial_id', 'category_ok', 'priority_ok'],
        properties: {
          trial_id: { type: 'string' },
          category_ok: { type: 'boolean' },
          priority_ok: { type: 'boolean' },
        },
      },
    },
  },
};

const SCAN_SCHEMA = {
  type: 'object',
  required: ['trials'],
  properties: {
    trials: {
      type: 'array',
      items: {
        type: 'object',
        required: ['trial_id', 'transcript_found', 'spe_paths_read', 'broad_searches', 'tool_calls', 'tool_errors', 'tokens'],
        properties: {
          trial_id: { type: 'string' },
          transcript_found: { type: 'boolean' },
          spe_paths_read: { type: 'array', items: { type: 'string' } },
          broad_searches: { type: 'array', items: { type: 'string' } },
          tool_calls: { type: 'integer', minimum: 0 },
          tool_errors: { type: 'integer', minimum: 0 },
          tokens: { type: 'integer', minimum: 0 },
        },
      },
    },
  },
};

const JUDGE_SCHEMA = {
  type: 'object',
  required: ['scores'],
  properties: {
    scores: {
      type: 'array',
      items: {
        type: 'object',
        required: ['item_id', 'score', 'pass', 'reason'],
        properties: {
          item_id: { type: 'string' },
          score: { type: 'integer' },
          pass: { type: 'boolean' },
          reason: { type: 'string' },
        },
      },
    },
  },
};

const FAILURE_SCHEMA = {
  type: 'object',
  required: ['types', 'grader_suspicions', 'harness_issues', 'proposals'],
  properties: {
    types: {
      type: 'array',
      items: {
        type: 'object',
        required: ['name', 'kind', 'existing_f_id', 'configs', 'count', 'what', 'how_to_spot', 'example_trial_ids', 'fix'],
        properties: {
          name: { type: 'string' },
          kind: { type: 'string' },
          existing_f_id: { type: 'string' },
          configs: { type: 'array', items: { type: 'string' } },
          count: { type: 'integer' },
          what: { type: 'string' },
          how_to_spot: { type: 'string' },
          example_trial_ids: { type: 'array', items: { type: 'string' } },
          fix: { type: 'string' },
        },
      },
    },
    grader_suspicions: { type: 'array', items: { type: 'string' } },
    harness_issues: { type: 'array', items: { type: 'string' } },
    proposals: { type: 'array', items: { type: 'string' } },
  },
};

const CRITIC_SCHEMA = {
  type: 'object',
  required: ['ready_for_closeout', 'gaps'],
  properties: {
    ready_for_closeout: { type: 'boolean' },
    gaps: {
      type: 'array',
      items: {
        type: 'object',
        required: ['gap', 'severity', 'evidence'],
        properties: {
          gap: { type: 'string' },
          severity: { type: 'string', enum: ['blocker', 'major', 'minor'] },
          evidence: { type: 'string' },
        },
      },
    },
    notes: { type: 'string' },
  },
};

// ---------- Prompts ----------
function trialPrompt(cfg, ticket) {
  return `You are one trial in an evaluation. Act as the support triage agent defined by config ${cfg} and handle one ticket.

1. Read spe/configs/${cfg}/prompt.md. Follow it as your system prompt.
2. Use only the tools listed in spe/configs/${cfg}/tools.md, called the way that file documents. Do not use any other command to look up ticket or customer data.
3. Read the ticket at spe/evals/tasks/tickets/${ticket}.json.

These rules apply to every trial:
- You may open only spe/configs/${cfg}/ and spe/evals/tasks/tickets/${ticket}.json inside spe/. Do not open, list, grep, find, or search anything else in spe/. That includes spe/evals/, spe/predictions/, spe/plans/, spe/spec/, and any results or logs. Do not search the repository from its root. Do not run git. A read outside these paths voids this trial.
- Do not create, edit, or delete any file.

Return the label (category and priority), the customer reply you wrote, the tools you called in order, how many tool calls returned an error, every file path you opened, and your status. Use "gave_up" only if you could not finish.`;
}

function gradePrompt(chunkId, lines) {
  const input = `spe/evals/runs/${R}/grade-input/${chunkId}.jsonl`;
  return `You are a grading clerk. You do not judge anything. You run the code grader and copy its output.

1. Create spe/evals/runs/${R}/grade-input/ if it does not exist.
2. Write the lines between the markers, verbatim, to ${input}.
3. Run: ${GRADE_CMD.replace('{input}', input)}
4. Return the grader's exit code. For every trial_id the grader printed, return its category_ok and priority_ok values exactly. Do not compute, infer, or correct any value. If the grader fails or skips a line, leave that line out and put the last 20 lines of stderr in stderr_tail.

Do not edit grade.py, answers.json, or any file except the one in step 2.

---BEGIN---
${lines}
---END---`;
}

function scanPrompt(group) {
  const list = group.map((r) => ({ trial_id: r.label, config: r.cfg, ticket: r.ticket }));
  return `You audit trial transcripts for answer-key peeks. The transcripts are under ${TRANSCRIPT_DIR}. Each one is identified by its agent label, and the label equals the trial_id.

For each trial below:
- Set transcript_found. If you cannot find the transcript, return zeros and empty lists.
- In spe_paths_read, list every path under spe/ that the trial read, listed, grepped, globbed, or passed to a command. Include all of them, allowed or not.
- In broad_searches, list every command that searched or listed a directory containing spe/ without naming a file, such as grep -r, rg, find, or ls -R run from the repository root or from spe/.
- From the transcript, count tool calls, tool calls that returned an error, and total tokens from the usage fields.

Do not open graders, answers, or predictions yourself. Do not edit any file.

Trials (JSON):
${JSON.stringify(list)}`;
}

function judgePrompt(items) {
  return `You are the tone judge. Read spe/evals/graders/judge.md and apply its rubric exactly as written.

For each item, read spe/evals/tasks/tickets/<ticket_id>.json for context. Then score the reply's tone on judge.md's scale, and decide pass or fail using judge.md's threshold. Give a one-sentence reason that quotes the reply.

Judge tone only. Do not judge whether the category or priority is right. You are not told which configuration wrote each reply, and you should not try to guess. Do not edit any file.

Items (JSON):
${JSON.stringify(items)}`;
}

// ---------- Stages ----------
async function runTrial(spec, ph) {
  const label = `${R}/${spec.cfg}/${spec.ticket}/t${spec.trial}`;
  if (!reserveTrial(label)) return { ...spec, label, outcome: 'skipped_budget' };
  const t0 = Date.now();
  try {
    const out = await agent(trialPrompt(spec.cfg, spec.ticket), {
      label, phase: ph, schema: TRIAL_SCHEMA, model: TRIAL_MODEL,
    });
    return { ...spec, label, outcome: 'completed', out, runtime_ms: Date.now() - t0 };
  } catch (e) {
    // A harness error or rate limit is not a model failure. It is excluded from metrics.
    return { ...spec, label, outcome: 'harness_error', error: errText(e), runtime_ms: Date.now() - t0 };
  }
}

async function gradeAll(done, ph, tag) {
  const groups = chunks(done, GRADE_CHUNK);
  const results = await parallel(groups.map((g, i) => async () => {
    const chunkId = `${tag}-${pad2(i + 1)}`;
    const lines = g.map((r) => JSON.stringify({
      trial_id: r.label,
      ticket_id: r.ticket,
      label: { category: r.out?.label?.category ?? '', priority: r.out?.label?.priority ?? '' },
    })).join('\n');
    const opts = { label: `${R}/grade/${chunkId}`, phase: ph, schema: GRADE_SCHEMA, model: CLERK_MODEL };
    try {
      return { chunkId, g, res: await agent(gradePrompt(chunkId, lines), opts) };
    } catch (e1) {
      try {
        return { chunkId, g, res: await agent(gradePrompt(chunkId, lines), opts) };
      } catch (e2) {
        return { chunkId, g, error: errText(e2) };
      }
    }
  }));
  for (const { chunkId, g, res, error } of results) {
    if (error) return halt(`grading clerk failed twice on ${chunkId}: ${error}`);
    if (res.grader_exit_code !== 0) return halt(`grade.py exited ${res.grader_exit_code} on ${chunkId}: ${res.stderr_tail ?? ''}`);
    const byId = new Map(res.results.map((x) => [x.trial_id, x]));
    for (const r of g) {
      const x = byId.get(r.label);
      if (!x) return halt(`grade.py output is missing ${r.label} (chunk ${chunkId})`);
      r.grade = { category_ok: x.category_ok, priority_ok: x.priority_ok, both_ok: x.category_ok && x.priority_ok };
    }
  }
}

async function scanAll(done, ph, tag) {
  const groups = chunks(done, SCAN_CHUNK);
  const results = await parallel(groups.map((g, i) => async () => {
    try {
      return { g, res: await agent(scanPrompt(g), {
        label: `${R}/scan/${tag}-${pad2(i + 1)}`, phase: ph, schema: SCAN_SCHEMA, model: CLERK_MODEL,
      }) };
    } catch (e) {
      return { g, error: errText(e) };
    }
  }));
  for (const { g, res, error } of results) {
    const byId = new Map((res?.trials ?? []).map((x) => [x.trial_id, x]));
    for (const r of g) {
      const x = byId.get(r.label);
      if (!x || !x.transcript_found) {
        r.unverified = true;
        r.voided = true;
        r.void_reason = r.void_reason ?? (error ? `scan error: ${error}` : 'transcript not found');
        continue;
      }
      r.scan = { tool_calls: x.tool_calls, tool_errors: x.tool_errors, tokens: x.tokens };
      const bad = x.spe_paths_read.filter(forbiddenFor(r)); // the forbidden decision is made in code
      if (bad.length || x.broad_searches.length) {
        r.voided = true;
        r.void_reason = `transcript: ${[...bad, ...x.broad_searches].join(', ')}`;
      }
    }
  }
  const unverified = done.filter((r) => r.unverified).length;
  if (done.length && unverified / done.length > UNVERIFIED_HALT_SHARE) {
    halt(`peek scan could not verify ${unverified}/${done.length} trials`);
  }
}

async function judgeAll(recs, ph, tag) {
  // Blind: shuffle across configs and replace trial labels with opaque item IDs.
  const order = [...recs].sort((a, b) => hash(a.label) - hash(b.label));
  const idOf = new Map(order.map((r) => [r.label, `J${hash('judge:' + r.label).toString(36)}`]));
  const groups = chunks(order, JUDGE_CHUNK);
  const results = await parallel(groups.map((g, i) => async () => {
    const items = g.map((r) => ({ item_id: idOf.get(r.label), ticket_id: r.ticket, reply: r.out.reply }));
    try {
      return { g, res: await agent(judgePrompt(items), {
        label: `${R}/judge/${tag}-${pad2(i + 1)}`, phase: ph, schema: JUDGE_SCHEMA, model: JUDGE_MODEL,
      }) };
    } catch (e) {
      return { g, error: errText(e) };
    }
  }));
  for (const { g, res, error } of results) {
    const byId = new Map((res?.scores ?? []).map((s) => [s.item_id, s]));
    for (const r of g) {
      const s = byId.get(idOf.get(r.label));
      if (s) r.judge = { score: s.score, pass: s.pass, reason: s.reason };
      else r.unjudged = error ?? 'missing from judge output';
    }
  }
}

async function runBatch(specs, names, tag) {
  enter(names.trials);
  const recs = await parallel(specs.map((s) => () => runTrial(s, names.trials)));
  const done = recs.filter((r) => r.outcome === 'completed');
  log(`${tag}: ${done.length} completed, ${recs.filter((r) => r.outcome === 'harness_error').length} harness errors, ${recs.filter((r) => r.outcome === 'skipped_budget').length} skipped for budget. Est. spend $${spent.toFixed(2)}`);

  for (const r of done) {
    const bad = (r.out.files_read ?? []).filter(forbiddenFor(r));
    if (bad.length) { r.voided = true; r.void_reason = `self-reported: ${bad.join(', ')}`; }
  }

  enter(names.grade);
  await gradeAll(done, names.grade, tag);
  if (halted) return recs;

  enter(names.scan);
  await scanAll(done, names.scan, tag);
  if (halted) return recs;
  log(`${tag}: ${done.filter((r) => r.voided).length} trials voided by the peek checks`);

  enter(names.judge);
  await judgeAll(done.filter((r) => !r.voided), names.judge, tag);
  return recs;
}

function summarize(recs) {
  const by = {};
  for (const cfg of CONFIGS) {
    const all = recs.filter((r) => r.cfg === cfg);
    const completed = all.filter((r) => r.outcome === 'completed');
    const valid = completed.filter(isValid);
    const judged = valid.filter((r) => r.judge);
    const scanned = valid.filter((r) => r.scan);
    const calls = scanned.reduce((a, r) => a + r.scan.tool_calls, 0);
    const errs = scanned.reduce((a, r) => a + r.scan.tool_errors, 0);
    const tok = mean(scanned.map((r) => r.scan.tokens));
    by[cfg] = {
      trials: all.length,
      completed: completed.length,
      harness_errors: all.filter((r) => r.outcome === 'harness_error').length,
      skipped_budget: all.filter((r) => r.outcome === 'skipped_budget').length,
      voided: completed.filter((r) => r.voided).length,
      valid_n: valid.length,
      category_acc: r3(rate(valid, (r) => r.grade.category_ok)),
      priority_acc: r3(rate(valid, (r) => r.grade.priority_ok)),
      both_acc: r3(rate(valid, (r) => r.grade.both_ok)),
      gave_up_rate: r3(rate(valid, (r) => r.out.status === 'gave_up')),
      tone_judged_n: judged.length,
      tone_mean: r3(mean(judged.map((r) => r.judge.score))),
      tone_pass_rate: r3(rate(judged, (r) => r.judge.pass)),
      runtime_s_mean: r3(mean(valid.map((r) => r.runtime_ms / 1000))),
      tool_calls_mean: r3(mean(scanned.map((r) => r.scan.tool_calls))),
      tokens_mean: tok == null ? null : Math.round(tok),
      tool_error_rate: calls ? r3(errs / calls) : null,
      check_status_rate: r3(rate(valid, (r) => (r.out.tool_calls ?? []).some((t) => /check_status/.test(t)))),
    };
  }
  return by;
}

function compact(r) {
  return {
    trial_id: r.label, cfg: r.cfg, ticket: r.ticket, trial: r.trial, topup: r.topup,
    outcome: r.outcome, error: r.error, label: r.out?.label, reply: r.out?.reply,
    status: r.out?.status, tool_calls: r.out?.tool_calls, runtime_ms: r.runtime_ms,
    grade: r.grade, scan: r.scan, judge: r.judge,
    voided: !!r.voided, void_reason: r.void_reason, unjudged: r.unjudged,
  };
}

// ---------- Main ----------
let cells = [];
for (const ticket of TICKETS) for (const cfg of CONFIGS) cells.push({ cfg, ticket });
if (ONLY) cells = cells.filter((c) => ONLY.includes(`${c.cfg}:${c.ticket}`));

// Trial index is the outer loop, so a budget cut removes the last trials evenly across configs and tickets.
const specs = [];
for (let t = 1; t <= TRIALS_PER_CELL; t++) {
  for (const c of cells) specs.push({ ...c, trial: t, topup: false });
}

const projected = specs.length * PER_TRIAL + SYNTH_RESERVE;
log(`${R}: configs ${CONFIGS.join(', ')}, ${cells.length} cells, ${specs.length} planned trials, est. $${PER_TRIAL.toFixed(3)} per trial, projected $${projected.toFixed(2)} before top-up, cap $${CAP_USD}`);
if (projected > CAP_USD) log(`WARNING: the projection crosses the cap, so the last planned trials will be skipped`);
if (!TRANSCRIPT_DIR) halt('args.transcriptDir is missing, so the peek scan cannot run');

const judgeNote = 'The judge is Opus, the same model family as the trials. No different-family judge is configured, so tone scores can share blind spots with the trial model.';

if (halted) return { round: R, halted, spend_estimate_usd: 0, cap_usd: CAP_USD };

const mainRecs = await runBatch(specs, { trials: 'Trials', grade: 'Grade', scan: 'Scan', judge: 'Judge' }, 'main');

// Top-up: cells where only some planned trials passed get extra trials, up to the caps.
let topRecs = [];
const tSpecs = [];
if (!halted && TOPUP_CAP > 0) {
  const splits = cells.filter((c) => {
    const v = mainRecs.filter((r) => r.cfg === c.cfg && r.ticket === c.ticket && isValid(r));
    const p = v.filter((r) => r.grade.both_ok).length;
    return p > 0 && p < v.length;
  }).sort((a, b) => hash(`${a.cfg}:${a.ticket}`) - hash(`${b.cfg}:${b.ticket}`));
  for (let k = 1; k <= TOPUP_PER_CELL; k++) {
    for (const c of splits) {
      if (tSpecs.length >= TOPUP_CAP) break;
      tSpecs.push({ ...c, trial: TRIALS_PER_CELL + k, topup: true });
    }
  }
  log(`${splits.length} split cells. Launching ${tSpecs.length} top-up trials (cap ${TOPUP_PER_CELL} per cell, ${TOPUP_CAP} total)`);
  if (tSpecs.length) {
    topRecs = await runBatch(tSpecs, { trials: 'Top-up', grade: 'Top-up', scan: 'Top-up', judge: 'Top-up' }, 'topup');
  }
}

const all = [...mainRecs, ...topRecs];
const accounting = {
  planned_trials: specs.length,
  topup_trials: tSpecs.length,
  skipped_trials: skipped.length,
  skipped_by_config: Object.fromEntries(CONFIGS.map((c) => [c, skipped.filter((l) => l.includes(`/${c}/`)).length])),
  harness_errors: all.filter((r) => r.outcome === 'harness_error').length,
  voided: all.filter((r) => r.voided).map((r) => ({ trial_id: r.label, reason: r.void_reason })),
  unverified: all.filter((r) => r.unverified).length,
  unjudged: all.filter((r) => r.unjudged).length,
  spend_estimate_usd: r2(spent),
  cap_usd: CAP_USD,
};

if (halted) {
  return { round: R, halted, accounting, skipped_trials: skipped, records: all.map(compact) };
}

enter('Synthesis');
spent += SYNTH_RESERVE;

// Headline metrics use only the planned trials, because the prediction assumed the planned trials per cell.
const metricsPrimary = summarize(mainRecs);
const metricsWithTopup = summarize(all);
const cellTable = cells.map((c) => {
  const pick = (recs) => recs.filter((r) => r.cfg === c.cfg && r.ticket === c.ticket && isValid(r));
  const p = pick(mainRecs);
  const t = pick(topRecs);
  return {
    cell: `${c.cfg}:${c.ticket}`,
    planned_pass: p.filter((r) => r.grade.both_ok).length, planned_valid: p.length,
    topup_pass: t.filter((r) => r.grade.both_ok).length, topup_valid: t.length,
  };
});

const failed = all.filter((r) => isValid(r) && (!r.grade.both_ok || (r.judge && !r.judge.pass)));
const failedForAnalysis = failed.slice(0, MAX_FAILURES_FOR_ANALYSIS).map((r) => ({
  trial_id: r.label, cfg: r.cfg, ticket: r.ticket, label: r.out.label,
  category_ok: r.grade.category_ok, priority_ok: r.grade.priority_ok,
  tone_pass: r.judge?.pass ?? null, tone_reason: r.judge?.reason ?? null,
  tools: r.out.tool_calls, status: r.out.status, note: r.out.note ?? '',
}));

let failureAnalysis = null;
try {
  failureAnalysis = await agent(`You are the failure analyst for SPE ${R}. All trials are finished. You may now read spe/evals/ (including answers.json and the graders) and spe/failures.md. Do not edit any file. Never edit spe/predictions/.

Group the failures below into failure types. If a type matches an entry in spe/failures.md, reuse its F-number in existing_f_id. Otherwise leave existing_f_id empty. For each type, give the name, kind (agent, grader, harness, or task), configs, count, What, How to spot it, example trial IDs, and Fix. Check whether any "failure" is really a wrong answer in answers.json or a grader bug, and list those in grader_suspicions. List any harness problems. Then propose what ${NEXT} should change.

There are ${failed.length} failed trials in total. ${failedForAnalysis.length} are shown here.
Per-config metrics (planned trials only): ${JSON.stringify(metricsPrimary)}
Failures (JSON): ${JSON.stringify(failedForAnalysis)}`,
    { label: `${R}/failure-analysis`, phase: 'Synthesis', schema: FAILURE_SCHEMA, model: 'opus' });
} catch (e) {
  log(`failure analysis errored: ${errText(e)}`);
}

let critic = null;
try {
  critic = await agent(`You are the completeness critic for SPE ${R}. Read spe/plans/${R}.md and spe/predictions/${R}.yaml. Treat them as read-only. Do not edit any file.

Check that this run measured everything the plan and the prediction need. Every predicted metric must have a measured number with its n for each config. The planned trials must have run, or their skips must be explained and balanced across configs. Voids, unverified scans, and unjudged replies must be few enough that the numbers still hold. Top-up trials must be kept out of the headline metrics. Report each gap with a severity and evidence. Set ready_for_closeout to false if any gap is a blocker.

Accounting: ${JSON.stringify(accounting)}
Metrics, planned trials only: ${JSON.stringify(metricsPrimary)}
Metrics with top-up: ${JSON.stringify(metricsWithTopup)}
Failure analysis: ${JSON.stringify(failureAnalysis)}
Judge note: ${judgeNote}`,
    { label: `${R}/completeness-critic`, phase: 'Synthesis', schema: CRITIC_SCHEMA, model: 'opus' });
} catch (e) {
  log(`completeness critic errored: ${errText(e)}`);
}

log(`${R} done. Est. spend $${spent.toFixed(2)} of $${CAP_USD}. Ready for close-out: ${critic ? critic.ready_for_closeout : 'unknown'}`);

// The close-out session writes these records to spe/evals/results/<round>/trials.jsonl for next round's control regrade.
return {
  round: R,
  halted: null,
  accounting: { ...accounting, spend_estimate_usd: r2(spent) },
  per_trial_estimate_usd: r3(PER_TRIAL),
  skipped_trials: skipped,
  metrics_primary: metricsPrimary,
  metrics_with_topup: metricsWithTopup,
  cells: cellTable,
  judge_note: judgeNote,
  failure_analysis: failureAnalysis,
  critic,
  records: all.map(compact),
};
```
